effect.shader:
#define EPS 0.00001
#define PI 3.14159265359
float lum(vec3 c) {
return dot(c, vec3(0.2126, 0.7152, 0.0722));
}
vec3 srgbToLinear(vec3 s) {
vec3 lo = s / 12.92;
vec3 hi = pow((s + 0.055) / 1.055, vec3(2.4));
return mix(lo, hi, step(vec3(0.04045), s));
}
vec3 linearToSrgb(vec3 l) {
vec3 lo = l * 12.92;
vec3 hi = 1.055 * pow(max(l, 0.0), vec3(1.0 / 2.4)) - 0.055;
return mix(lo, hi, step(vec3(0.0031308), l));
}
float noiseHash(vec2 p) {
vec3 p3 = fract(vec3(p.xyx) * 0.1031);
p3 += dot(p3, p3.yzx + 33.33);
return fract((p3.x + p3.y) * p3.z);
}
float getTaps(float q) {
if (q < 1.5) return 8.0;
if (q < 2.5) return 14.0;
return 20.0;
}
vec4 blurPass(sampler2D tex, vec2 texOff, vec2 st, float numPx) {
if (numPx <= 0.0) return texture2DCv(tex, st);
float sigma = numPx / 2.14596602;
sigma = max(sigma, EPS);
mediump vec3 ig;
ig.x = 1.0 / (sqrt(2.0 * PI) * sigma);
ig.y = exp(-0.5 / (sigma * sigma));
ig.z = ig.y * ig.y;
vec4 avg = texture2DCv(tex, st) * ig.x;
float cSum = ig.x;
for (float i = 1.0; i <= 64.0; i += 2.0) {
if (i > numPx) break;
ig.xy *= ig.yz;
cSum += 2.0 * ig.x;
float w0 = ig.x;
ig.xy *= ig.yz;
cSum += 2.0 * ig.x;
float w1 = ig.x;
float wL = w0 + w1;
float oL = (i * w0 + (i + 1.0) * w1) / max(wL, EPS);
avg += texture2DCv(tex, clamp(st - oL * texOff, 0.0, 1.0)) * wL;
avg += texture2DCv(tex, clamp(st + oL * texOff, 0.0, 1.0)) * wL;
}
return avg / max(cSum, EPS);
}
void main() {
vec2 uv = acScreenNorm;
float taps = getTaps(float(quality));
float r1 = glowRadius * 0.5;
float r2 = glowRadius * glowSpread * 0.5;
if (acPass == 0) {
vec4 src = texture2DCv(inputImg.texture, uv);
vec3 rgb = max(src.rgb, 0.0);
vec3 lin = srgbToLinear(rgb);
float brightness = lum(lin);
brightness = pow(max(brightness, 0.0), threshGamma);
float knee = max(softKnee, EPS);
float edge = brightness - threshold + knee;
edge = clamp(edge / (2.0 * knee), 0.0, 1.0);
edge *= edge;
float mask = max(edge, max(brightness - threshold, 0.0));
mask = mask / max(brightness, EPS);
vec3 extracted = rgb * mask;
gl_FragColor = vec4(extracted, src.a);
return;
}
if (acPass == 1) {
vec2 to = vec2(1.0 / glowA.size.x, 0.0);
float ks = r1 * (taps / 10.0);
gl_FragColor = blurPass(glowA.texture, to, uv, ks);
return;
}
if (acPass == 2) {
vec2 to = vec2(0.0, 1.0 / glowB.size.y);
float ks = r1 * (taps / 10.0);
gl_FragColor = blurPass(glowB.texture, to, uv, ks);
return;
}
if (acPass == 3) {
vec2 to = vec2(1.0 / glowA.size.x, 0.0);
float ks = r2 * (taps / 10.0);
gl_FragColor = blurPass(glowA.texture, to, uv, ks);
return;
}
vec4 src = texture2DCv(inputImg.texture, uv);
vec3 baseRGB = max(src.rgb, 0.0);
vec3 innerGlow = max(texture2DCv(glowC.texture, uv).rgb, 0.0);
vec3 outerGlow = max(texture2DCv(glowD.texture, uv).rgb, 0.0);
vec3 innerLin = srgbToLinear(innerGlow);
vec3 outerLin = srgbToLinear(outerGlow);
vec3 baseLin = srgbToLinear(baseRGB);
float baseLum = lum(baseLin);
vec3 totalGlow = innerLin * innerWeight + outerLin * outerWeight * tailWeight;
totalGlow = mix(innerLin * innerWeight, totalGlow, glowSoftness);
if (hlGlowStr > EPS) {
float hlMask = smoothstep(hlThreshold - 0.1, hlThreshold + 0.1, baseLum);
vec3 hlGlow = outerLin * hlMask;
if (abs(hlSaturation - 1.0) > EPS) {
float hlL = lum(hlGlow);
hlGlow = mix(vec3(hlL), hlGlow, hlSaturation);
}
totalGlow += hlGlow * hlGlowStr * 0.5;
}
if (colorPreserve > EPS) {
float glowLum = lum(totalGlow);
if (baseLum > EPS && glowLum > EPS) {
vec3 baseColor = baseLin / max(baseLum, EPS);
vec3 coloredGlow = baseColor * glowLum;
totalGlow = mix(totalGlow, coloredGlow, colorPreserve * 0.5);
}
}
if (abs(glowSatBoost - 1.0) > EPS) {
float gL = lum(totalGlow);
totalGlow = mix(vec3(gL), totalGlow, glowSatBoost);
}
if (abs(glowWarmth) > EPS) {
float gL = lum(totalGlow);
totalGlow.r += glowWarmth * 0.04 * gL;
totalGlow.b -= glowWarmth * 0.03 * gL;
}
if (glowTintStr > EPS) {
totalGlow = mix(totalGlow, totalGlow * srgbToLinear(glowTint.rgb), glowTintStr);
}
if (halStr > EPS) {
float halLum = lum(outerLin);
float halMask = smoothstep(0.2, 0.6, halLum);
vec3 halation = outerLin * srgbToLinear(halColor.rgb) * halMask;
totalGlow += halation * halStr * 0.5;
}
if (diffAmount > EPS) {
vec3 diffGlow = mix(innerLin, outerLin, 0.5);
float diffHL = smoothstep(0.3, 0.8, baseLum);
diffGlow *= mix(1.0, diffHL, diffHighlights);
totalGlow += diffGlow * diffAmount * 0.3;
}
totalGlow *= glowAmount;
totalGlow = 1.0 - exp(-totalGlow * softClipKnee);
vec3 glowSRGB = linearToSrgb(max(totalGlow, 0.0));
if (glowOnly) {
gl_FragColor = vec4(clamp(glowSRGB, 0.0, 1.0), 1.0);
return;
}
vec3 comp;
float bm = float(blendMode);
if (bm < 1.5) {
comp = baseLin + srgbToLinear(max(glowSRGB, 0.0));
} else if (bm < 2.5) {
comp = srgbToLinear(1.0 - (1.0 - baseRGB) * (1.0 - clamp(glowSRGB, 0.0, 1.0)));
} else if (bm < 3.5) {
vec3 gC = clamp(glowSRGB, 0.0, 1.0);
vec3 r;
r.r = (gC.r<0.5) ? 2.0*baseRGB.r*gC.r+baseRGB.r*baseRGB.r*(1.0-2.0*gC.r) : 2.0*baseRGB.r*(1.0-gC.r)+sqrt(max(baseRGB.r,0.0))*(2.0*gC.r-1.0);
r.g = (gC.g<0.5) ? 2.0*baseRGB.g*gC.g+baseRGB.g*baseRGB.g*(1.0-2.0*gC.g) : 2.0*baseRGB.g*(1.0-gC.g)+sqrt(max(baseRGB.g,0.0))*(2.0*gC.g-1.0);
r.b = (gC.b<0.5) ? 2.0*baseRGB.b*gC.b+baseRGB.b*baseRGB.b*(1.0-2.0*gC.b) : 2.0*baseRGB.b*(1.0-gC.b)+sqrt(max(baseRGB.b,0.0))*(2.0*gC.b-1.0);
comp = srgbToLinear(r);
} else {
comp = max(baseLin, srgbToLinear(max(glowSRGB, 0.0)));
}
vec3 fin = linearToSrgb(max(comp, 0.0));
if (abs(filmSaturation - 1.0) > EPS) {
float fl = lum(fin);
fin = mix(vec3(fl), fin, filmSaturation);
}
if (abs(filmContrast) > 0.5) {
float fc = filmContrast / 100.0;
float fl = lum(fin);
float sCurve = fl + fc * 0.5 * (fl - 0.5) * (1.0 - abs(fl - 0.5) * 2.0);
float ratio = sCurve / max(fl, EPS);
fin *= ratio;
}
if (abs(filmWarmth) > EPS) {
fin.r += filmWarmth * 0.06;
fin.b -= filmWarmth * 0.04;
}
if (filmFade > EPS) {
fin = fin * (1.0 - filmFade * 0.15) + filmFade * 0.1;
float fl = lum(fin);
fin = mix(fin, vec3(fl), filmFade * 0.2);
}
if (filmGrain > EPS) {
vec2 px = floor(inputImg.size * uv);
float n = noiseHash(px + acTime * 100.0) * 2.0 - 1.0;
float fl = lum(fin);
float grainMask = 1.0 - fl * 0.4;
fin += n * filmGrain * 0.08 * grainMask;
}
if (ditherAmt > EPS) {
vec2 px = floor(inputImg.size * uv);
float n1 = fract(sin(dot(px, vec2(12.9898, 78.233))) * 43758.5453);
float n2 = fract(sin(dot(px, vec2(24.123, 17.321))) * 12345.6789);
float n3 = fract(sin(dot(px, vec2(93.989, 67.345))) * 98765.4321);
fin += (vec3(n1, n2, n3) - 0.5) * ditherAmt;
}
fin = mix(baseRGB, fin, globalMix);
fin = clamp(fin, 0.0, 1.0);
gl_FragColor = vec4(fin, src.a);
}
